import type { BenchmarkId } from "@/types/leaderboard";

/** Which of our own measurements drives a single-series bar chart. */
export type BarMetric = "index" | "cost" | "time" | BenchmarkId;

export type TabRender =
  | { kind: "bar"; metric: BarMetric }
  /** All three benchmarks side by side (`benchmark-score-by-eval`). */
  | { kind: "grouped" }
  | { kind: "empty"; reason: string };

/**
 * Which colour key the panel's legend slot carries. `"benchmark"` is the
 * multi-series key, `"creator"` the per-creator chip row (which also brings an
 * 8px `mt-2` with it); most tabs have neither and ship the empty 0-height slot.
 */
export type TabLegend = "none" | "benchmark" | "creator";

export interface TabNote {
  title: string;
  /** Rendered as one `<p>` each inside MetricAccordion's `space-y-2`. */
  paras: string[];
}

export interface TabSpec {
  /** URL slug; also the Radix Tabs value. */
  slug: string;
  /** Tab trigger text. */
  label: string;
  /** Panel `h3`. */
  title: string;
  caption: string;
  notes: TabNote[];
  showColorBy: boolean;
  showModelPicker: boolean;
  /** Measured chart height in px. */
  chartHeight: number;
  legend: TabLegend;
  /**
   * Render the panel body the way the SCATTER cards do — a quadrant key above
   * the legend slot and the chart in `relative mt-2 overflow-x-scroll
   * 2xl:overflow-visible` (watermark inset 12). Measured on one tab.
   */
  scatterBody: boolean;
  render: TabRender;
}

export type ScatterRender =
  | { kind: "scatter"; metric: "cost" | "time" }
  | { kind: "empty"; reason: string };

export interface ScatterSpec {
  title: string;
  caption: string;
  note: TabNote;
  chartHeight: number;
  render: ScatterRender;
}

export interface SectionSpec {
  /** Anchor id; matches the scroll-spy sidebar href. */
  id: string;
  heading: string;
  description: string;
  /** URL query param the active tab mirrors into. */
  param: string;
  tabs: TabSpec[];
  /** The `p-8` scatter card below the tabbed card, where the target has one. */
  scatter?: ScatterSpec;
}

